class MatchProbePDO extends PDO
{
    public array $statements=[];
    public bool $loseCommit=false;
    public $onPrepare=null;
    private function observe(string $sql): void{$this->statements[]=$sql;if($this->onPrepare!==null)($this->onPrepare)($sql);}
    private function acknowledge(): void{if($this->loseCommit){$this->loseCommit=false;throw new RuntimeException('Lost commit acknowledgement');}}
    #[\ReturnTypeWillChange]
    public function prepare($sql,$options=[]){$this->observe($sql);return parent::prepare($sql,$options);}
    #[\ReturnTypeWillChange]
    public function query($sql,?int$mode=null,...$args){$this->observe($sql);return$mode===null?parent::query($sql):parent::query($sql,$mode,...$args);}
    #[\ReturnTypeWillChange]
    public function exec($sql){$this->observe($sql);$result=parent::exec($sql);if(strtoupper(trim($sql))==='COMMIT')$this->acknowledge();return$result;}
    #[\ReturnTypeWillChange]
    public function commit(){$result=parent::commit();$this->acknowledge();return$result;}
}
function connectMatch(string $target): MatchProbePDO
{
    $mysql=strpos($target,'mysql:')===0;
    if($mysql&&!preg_match('/^mysql:host=127\.0\.0\.1;port=[0-9]{1,5};dbname=task1013_[a-f0-9]+;charset=utf8mb4$/D',$target))throw new RuntimeException('Only own explicit task1013 loopback test DB allowed');
    $p=new MatchProbePDO($mysql?$target:'sqlite:'.$target,$mysql?getenv('HORIZON_MATCHES_TEST_USER'):null,$mysql?getenv('HORIZON_MATCHES_TEST_PASSWORD'):null,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);
    if(!$mysql){$p->exec('PRAGMA foreign_keys=ON');$p->exec('PRAGMA busy_timeout=5000');$p->exec('PRAGMA journal_mode=WAL');}
    return$p;
}
