    $pending=$store->get($seedIds[21]);$state=json_decode($pdo->query("SELECT data FROM inbox_state WHERE user_id='".$fullA."'")->fetchColumn(),true,512,JSON_THROW_ON_ERROR);$state['entries']=array_slice($state['entries'],1);$pdo->prepare('UPDATE inbox_state SET data=? WHERE user_id=?')->execute([InboxRules::json($state),$fullA]);$pdo->loseCommit=true;check(false,$s->deliverNotice($pending['id']),'Lost handoff commit ACK remains uncertain');check(null,$store->get($pending['id'])['notice'],'Lost ACK committed source consumption');check(false,$s->deliverNotice($pending['id']),'Retry cannot recreate delivered notice');$delivered=$inbox->get($fullA)['entries'];check(1,count(array_filter($delivered,static function($e)use($pending){return$e['reference']===$pending['id'];})),'Exactly one original notice after lost handoff response');
    // Superseded turn must never deliver its former recipient after the gameplay CAS.
    $oldNotice=$store->get($seedIds[0])['notice'];$v=$store->get($seedIds[0]);$next=MatchTransitions::turn($v,$fullA,2,false,$now);$scope->run(static function()use($store,$v,$next){$store->save($v,$next,"\0\xff");});check(false,$s->deliverNotice($seedIds[0]),'New recipient remains full without delivering stale old notice');check(true,$oldNotice['operationId']!==$store->get($seedIds[0])['notice']['operationId'],'Distinct per-turn original operation IDs');
    if($dsn){
