        $scope->run(static function()use($pdo,$a){for($start=0;$start<10000;$start+=100){$values=[];$args=[];for($i=$start;$i<$start+100;$i++){$values[]='('.implode(',',array_fill(0,14,'?')).')';array_push($args,sprintf('11111111-0000-4000-8000-%012d',$i),1,1,1,0,$a,'lobby','open',777,1,9999999999999,777,'{}','{}');}$pdo->prepare('INSERT INTO matches_state VALUES'.implode(',',$values))->execute($args);}});
        $after=['strength'=>777,'id'=>'11111111-0000-4000-8000-000000009000'];$queries=['open'=>$store->openSql(777,777,$after,256,true),'due'=>$store->dueSql(['cutoff'=>777,'afterDue'=>777,'afterId'=>$after['id']],20,true)];$proof=[];
        foreach($queries as$kind=>[$sql,$args]){$q=$pdo->prepare($sql);$q->execute($args);check($kind==='open'?256:20,count($q->fetchAll()),'Actual MySQL bounded '.$kind);$q=$pdo->prepare('EXPLAIN ANALYZE '.$sql);$q->execute($args);$plan=$q->fetchColumn();preg_match_all('/actual time=[^ ]+ rows=([0-9]+) loops=/',$plan,$hits);$work=max(array_map('intval',$hits[1]));check(true,$work<=($kind==='open'?256:20),'Deep MySQL seek visits only bounded rows');$bad=str_replace('id>?',"CONCAT(id,'')>?",$sql);$optimizer=$pdo->query('SELECT @@optimizer_switch')->fetchColumn();$pdo->exec("SET optimizer_switch='index_condition_pushdown=off'");try{$q=$pdo->prepare('EXPLAIN ANALYZE '.$bad);$q->execute($args);$negative=$q->fetchColumn();}finally{$pdo->exec('SET optimizer_switch='.$pdo->quote($optimizer));}preg_match_all('/actual time=[^ ]+ rows=([0-9]+) loops=/',$negative,$hits);$negativeWork=max(array_map('intval',$hits[1]));if($negativeWork<=9000)throw new RuntimeException('Negative control did not expose index scan work: '.$negative);check(true,$negativeWork>9000,'Non-sargable MySQL negative control with ICP disabled exposes old rows');$proof[$kind]=['actualRows'=>$work,'negativeRows'=>$negativeWork,'plan'=>$plan,'negativeControl'=>$negative];}
